    private static void verifyFileReadGrantSidecarExit(Path trace) throws Exception {
        String valid = validFileReadGrantSidecarExitTrace(false, false);
        assertFileReadGrantSidecarExitAccepted(trace, valid,
                "reused command ids in distinct generations");
        assertFileReadGrantSidecarExitAccepted(trace,
                validFileReadGrantSidecarExitTrace(true, false),
                "old security-scoped grant and fresh unscoped grant");
        String freshScoped = validFileReadGrantSidecarExitTrace(false, true);
        assertFileReadGrantSidecarExitAccepted(trace, freshScoped,
                "old unscoped grant and fresh security-scoped grant");
        assertFileReadGrantSidecarExitAccepted(trace,
                moveEventBefore(freshScoped,
                        fileReadGrantLifecycleEvent(
                                "fileReadGrant.closed", 1, "sidecar-exit"),
                        fileReadGrantPointerEvent("recovered-select-first",
                                "file-read-grant-secondary",
                                FILE_READ_GRANT_SESSION,
                                "file-read-grant-secondary")),
                "asynchronous old-grant close after recovered ready");

        for (String required : new String[]{
                fileReadGrantExitInjectionEvent(),
                fileReadGrantSidecarExitEvent(),
                fileReadGrantRecoveryScheduledEvent(),
                fileReadGrantRecoveryReadyEvent(),
                capabilityGenerationReadyEvent(2),
                fileReadGrantLoadedEvent("main", 1),
                fileReadGrantLoadedEvent("file-read-grant-secondary", 1),
                fileReadGrantLifecycleEvent(
                        "fileReadGrant.invalidated", 1, "sidecar-exit"),
                fileReadGrantLifecycleEvent(
                        "fileReadGrant.closed", 1, "sidecar-exit"),
                fileReadGrantGenerationTwo(fileReadGrantLifecycleEvent(
                        "fileReadGrant.closed", 2, "released")),
                fileReadGrantPanelEvent("recovered",
                        "Flow file read grant explicit release")}) {
            assertFileReadGrantSidecarExitRejected(trace, valid,
                    valid.replace(required, ""),
                    "missing required exit, recovery, cleanup or panel evidence");
        }
        assertFileReadGrantSidecarExitRejected(trace, valid,
                valid + fileReadGrantRecoveryScheduledEvent(),
                "duplicate recovery attempt");
        assertFileReadGrantSidecarExitRejected(trace, valid,
                valid.replace("\"windowsReloaded\":2",
                        "\"windowsReloaded\":1"),
                "not both retained windows reloaded");
        assertFileReadGrantSidecarExitRejected(trace, valid,
                valid + fileReadGrantSecondaryCreateEvent(),
                "secondary was recreated rather than retained");
        assertFileReadGrantSidecarExitRejected(trace, valid,
                valid.replace(fileReadGrantLoadedEvent(
                                "file-read-grant-secondary", 1),
                        fileReadGrantLoadedEvent("file-read-grant-secondary", 1)
                                .replace("\"sessionId\":\""
                                                + FILE_READ_GRANT_SESSION + "\"",
                                        "\"sessionId\":\"flow-ipc-session\"")),
                "recovered secondary load changed scope");
        assertFileReadGrantSidecarExitRejected(trace, valid,
                valid.replace(fileReadGrantSidecarExitAcceptanceEvent(false, false),
                        fileReadGrantAcceptanceEvent()),
                "owner-close acceptance cannot substitute for exit acceptance");
        assertFileReadGrantSidecarExitRejected(trace, valid,
                valid.replace("\"expected\":false", "\"expected\":true"),
                "expected exit instead of injected failure");
        assertFileReadGrantSidecarExitRejected(trace, valid,
                valid.replace(fileReadGrantExitInjectionEvent(),
                        fileReadGrantExitInjectionEvent().replace(
                                "\"processIdentifier\":121",
                                "\"processIdentifier\":222")),
                "failure injected into the wrong process");
        assertFileReadGrantSidecarExitRejected(trace, valid,
                valid.replace(fileReadGrantLifecycleEvent(
                                "fileReadGrant.invalidated", 1, "sidecar-exit"),
                        fileReadGrantLifecycleEvent(
                                "fileReadGrant.invalidated", 1,
                                "owner-window-closed")),
                "owner-close cleanup cannot substitute for sidecar exit");
        assertFileReadGrantSidecarExitRejected(trace, valid,
                valid.replace(
                        fileReadGrantGenerationTwo(fileReadGrantDataResultEvent()),
                        fileReadGrantDataResultEvent()),
                "fresh read result uses stale generation");
        assertFileReadGrantSidecarExitRejected(trace, valid,
                valid.replace(fileReadGrantGenerationTwo(
                                fileReadGrantSelectionResultEvent(
                                        "file-grant-open-first",
                                        "Flow file read grant explicit release")),
                        fileReadGrantSelectionResultEvent(
                                "file-grant-open-first",
                                "Flow file read grant explicit release")),
                "reused id cannot correlate a stale selection result");
        assertFileReadGrantSidecarExitRejected(trace, valid,
                valid.replace(fileReadGrantGenerationTwo(
                                fileReadGrantLifecycleEvent(
                                        "fileReadGrant.created", 2, "")),
                        fileReadGrantLifecycleEvent(
                                "fileReadGrant.created", 2, "")),
                "fresh grant created in stale generation");
        assertFileReadGrantSidecarExitRejected(trace, valid,
                valid.replace("\"diagnosticId\":2", "\"diagnosticId\":1"),
                "fresh grant reuses retired diagnostic identity");
        assertFileReadGrantSidecarExitRejected(trace, valid,
                moveEventBefore(valid,
                        fileReadGrantLifecycleEvent(
                                "fileReadGrant.invalidated", 1, "sidecar-exit"),
                        fileReadGrantSidecarExitEvent()),
                "revocation predates actual sidecar exit");
        for (String field : new String[]{
                "windowRetained", "webViewRetained",
                "secondaryWindowRetained", "secondaryWebViewRetained",
                "processReplaced", "recoveredStateResetObserved"}) {
            assertFileReadGrantSidecarExitRejected(trace, valid,
                    valid.replace("\"" + field + "\":true",
                            "\"" + field + "\":false"),
                    "missing recovered identity evidence: " + field);
        }
        assertFileReadGrantSidecarExitRejected(trace, valid,
                valid.replace("\"failedProcessIdentifier\":121",
                        "\"failedProcessIdentifier\":222"),
                "failed PID differs from initial PID");
        assertFileReadGrantSidecarExitRejected(trace, valid,
                valid.replace("\"recoveredProcessIdentifier\":222",
                        "\"recoveredProcessIdentifier\":121"),
                "recovered PID must differ");
        assertFileReadGrantSidecarExitRejected(trace, valid,
                valid.replace("\"oldSecondaryRequestBaseline\":2",
                        "\"oldSecondaryRequestBaseline\":1"),
                "old generation request baseline is not balanced");
        assertFileReadGrantSidecarExitRejected(trace, valid,
                valid.replace("\"oldSecondaryRequestCount\":3",
                                "\"oldSecondaryRequestCount\":2")
                        .replace("\"oldSecondaryResponseCount\":3",
                                "\"oldSecondaryResponseCount\":2"),
                "old generation selection has no UIDL advance");
        assertFileReadGrantSidecarExitRejected(trace, valid,
                valid.replace("\"mainRequestCount\":3",
                                "\"mainRequestCount\":2")
                        .replace("\"mainResponseCount\":3",
                                "\"mainResponseCount\":2"),
                "recovered main close has no UIDL advance");
        assertFileReadGrantSidecarExitRejected(trace, valid,
                valid.replace(fileReadGrantPanelEvent("recovered",
                                "Flow file read grant explicit release"),
                        fileReadGrantPanelEvent("recovered",
                                "Flow file read grant explicit release")
                                .replace("\"panelURLVerified\":true",
                                        "\"panelURLVerified\":false")),
                "fresh panel did not verify the selected URL");
        assertFileReadGrantSidecarExitRejected(trace, valid,
                valid.replace("external-native-panel-selection",
                        "appkit-window-key-event"),
                "old ineffective keyboard mode is not panel selection");
        assertFileReadGrantSidecarExitRejected(trace, valid,
                valid.replace("\"physicalInput\":false",
                        "\"physicalInput\":true"),
                "physical input claim");
        assertFileReadGrantSidecarExitRejected(trace, freshScoped,
                freshScoped.replace("\"securityScopeStopped\":true",
                        "\"securityScopeStopped\":false"),
                "fresh security-scoped access not stopped");
        String oldScoped = validFileReadGrantSidecarExitTrace(true, false);
        assertFileReadGrantSidecarExitRejected(trace, oldScoped,
                oldScoped.replace("\"securityScopeStopped\":true",
                        "\"securityScopeStopped\":false"),
                "old security-scoped access not stopped on sidecar exit");
        for (String secret : new String[]{
                FILE_READ_GRANT_RAW_TOKEN, FILE_READ_GRANT_FIXTURE_FILENAME,
                FILE_READ_GRANT_FIXTURE_CONTENT,
                Base64.getEncoder().withoutPadding().encodeToString(
                        FILE_READ_GRANT_FIXTURE_CONTENT.substring(0, 19)
                                .getBytes(StandardCharsets.UTF_8))}) {
            assertFileReadGrantSidecarExitRejected(trace, valid,
                    valid + "DEBUG " + secret + "\n", "raw-line privacy leak");
        }
        assertFileReadGrantSidecarExitRejected(trace, valid,
                valid.replace("\"bodyBytes\":19,\"bodyRedacted\":true",
                        "\"bodyBytes\":19,\"bodyRedacted\":true,"
                                + "\"bodyBase64\":\"dmF0b3Jp\""),
                "encoded body leaked under the canonical field");
        assertFileReadGrantSidecarExitRejected(trace, valid,
                valid.replace("\"bodyBytes\":19,\"bodyRedacted\":true",
                        "\"bodyBytes\":19,\"bodyRedacted\":true,"
                                + "\"encodedBodyAlias\":\""
                                + Base64.getEncoder().encodeToString(
                                FILE_READ_GRANT_FIXTURE_CONTENT.substring(0, 19)
                                        .getBytes(StandardCharsets.UTF_8))
                                + "\""),
                "encoded body leaked under an alias");
    }

