        List<String> opening = editRecoveryTrip(1); events.addAll(opening.subList(0, 3)); events.add(editIsolationCommand(false));
        events.add(editRecoveryScope(mainCloseRecoveryMainCreateEvent(), false, 1)); events.add(editIsolationCommand(true)); events.addAll(opening.subList(3, 6));
        events.add(fileReadGrantLoadedEvent(EDIT_ISOLATION_OWNER, 0)); appendEditRecoveryBaseline(events, false, 1);
        events.add(editRecoveryCheckpoint(1, false, mask)); events.add(editRecoveryDispatch(2, false)); events.add(editRecoveryDispatch(2, true));
        events.addAll(editRecoveryTrip(2)); events.add(editRecoveryCheckpoint(2, false, mask)); events.add(editRecoveryPrepared(mask));
