    private static String validFileDialogOutcomesTrace() {
        StringBuilder trace = new StringBuilder();
        trace.append(protocol(
                "recv", "launch", "{\"transport\":\"flow-ipc\"}"));
        trace.append(capabilityPermissionManifest()
                .replace("permission-secondary", "file-dialog-outcomes-secondary"));
        trace.append(protocol(
                "send", "launch.sidecar",
                "{\"generation\":1,\"transport\":\"flow-ipc\"}"));
        trace.append(protocol(
                "recv", "sidecar.started",
                "{\"generation\":1,\"processIdentifier\":101,"
                        + "\"transport\":\"flow-ipc\"}"));
        trace.append(capabilityGenerationReadyEvent(1));
        trace.append(protocol(
                "recv", "window.create", "{\"windowId\":\"main\"}"));
        trace.append(protocol(
                "recv", "standardBundleReady",
                "{\"requestTransport\":\"opaque-http-stream-ipc\"}"));
        trace.append(protocol(
                "recv", "standardBundleResource",
                "{\"path\":\"/VAADIN/build/FlowClient-file-dialog.js\"}"));
        trace.append(protocol(
                "recv", "webview.firstMeaningfulPaint", "{}"));
        for (String requestId : new String[]{"dialog-bootstrap", "dialog-uidl"}) {
            trace.append(protocol(
                    "send", "opaqueHttpStreamOpen",
                    "{\"requestId\":\"" + requestId + "\"}"));
            trace.append(protocol(
                    "recv", "opaqueHttpStreamResponse",
                    "{\"requestId\":\"" + requestId
                            + "\",\"status\":200}"));
            trace.append(protocol(
                    "recv", "opaqueHttpStreamResponseEnd",
                    "{\"requestId\":\"" + requestId + "\"}"));
        }
        trace.append(protocol(
                "recv", "opaquePushConnected",
                "{\"windowId\":\"main\","
                        + "\"sessionId\":\"flow-ipc-session\","
                        + "\"uiId\":\"main\"}"));
        trace.append(fileDialogOutcomesPointerEvent(
                "main-first", "main", "flow-ipc-session", "main", true));
        trace.append(fileDialogOutcomesCommandEvent(
                "dialog-first", "main", "flow-ipc-session", "main",
                "Flow file dialog normal cancel"));
        trace.append(fileDialogOutcomesPanelEvent());
        trace.append(fileDialogOutcomesPointerEvent(
                "main-concurrent", "main", "flow-ipc-session", "main", false));
        trace.append(fileDialogOutcomesCommandEvent(
                "dialog-concurrent", "main", "flow-ipc-session", "main",
                "Flow file dialog concurrent invocation"));
        trace.append(fileDialogOutcomesConcurrentResultEvent());
        trace.append(fileDialogOutcomesCancelEvent());
        trace.append(fileDialogOutcomesFirstResultEvent());
        trace.append(fileDialogOutcomesPushEvent());
        trace.append(fileDialogOutcomesPushAckEvent());
        trace.append(fileDialogOutcomesPointerEvent(
                "secondary-denied", "file-dialog-outcomes-secondary",
                FILE_DIALOG_OUTCOMES_SESSION,
                "file-dialog-outcomes-secondary", true));
        trace.append(fileDialogOutcomesCommandEvent(
                "dialog-denied", "file-dialog-outcomes-secondary",
                FILE_DIALOG_OUTCOMES_SESSION,
                "file-dialog-outcomes-secondary",
                "Flow file dialog denied invocation"));
        trace.append(fileDialogOutcomesDeniedResultEvent());
        trace.append(fileDialogOutcomesSecondaryPushEvent());
        trace.append(fileDialogOutcomesSecondaryPushAckEvent());
        trace.append(fileDialogOutcomesAcceptanceEvent());
        trace.append(fileDialogOutcomesShutdownEvent());
        return trace.toString();
    }

