    private static String validFileReadGrantRangeTrace(boolean scoped) {
        String base = validFileReadGrantTrace();
        String initialPointer = fileReadGrantPointerEvent("main-open-secondary", "main", "flow-ipc-session", "main");
        String manifest = protocolPreservingStringWhitespace("recv", "capabilityManifest", """
                {"path":"$APP/Contents/Resources/desktop-capabilities.json","loaded":true,
                "permissionMode":"manifest-enforced","parseError":"","commandsByWindow":{"main":[
                "fileDialog.openReadGrant","fileGrant.read","fileGrant.release","window.close"]}}
                """);
        StringBuilder trace = new StringBuilder(base.substring(0, base.indexOf(initialPointer))
                .replace(fileReadGrantManifestEvent(), manifest)
                .replace(protocol("recv", "window.create", "{\"windowId\":\"main\"}"),
                        mainCloseRecoveryMainCreateEvent() + fileReadGrantLoadedEvent("main", 0)));
        for (int stage = 0; stage < 10; stage++) {
            trace.append(rangeMainEvent(fileReadGrantPointerEvent(fileReadGrantRangeStageNames().get(stage), "main", "flow-ipc-session", "main")));
            trace.append(fileReadGrantRangeCommandEvent(stage));
            if (stage == 0) {
                trace.append(rangeMainEvent(fileReadGrantPanelEvent("file", "Flow file read grant bounded ranges")));
                trace.append(rangeMainEvent(fileReadGrantLifecycleEvent("fileReadGrant.created", 1, "")).replace("\"byteCount\":48", "\"byteCount\":65573"));
                trace.append(rangeMainEvent(fileReadGrantSelectionResultEvent("range-command-0", "Flow file read grant bounded ranges"))
                        .replace("[redacted length=34]", "[redacted length=40]").replace("\"byteCount\":48", "\"byteCount\":65573"));
                trace.append(fileDialogOutcomesPushEvent()).append(fileDialogOutcomesPushAckEvent());
            } else if (stage == 9) {
                trace.append(rangeMainEvent(fileReadGrantLifecycleEvent("fileReadGrant.releaseScheduled", 1, "released")));
                trace.append(rangeMainEvent(fileReadGrantLifecycleEvent("fileReadGrant.closed", 1, "released")));
                trace.append(rangeMainEvent(fileReadGrantReleaseResultEvent()).replace("file-grant-release-first", "range-command-9"));
            } else {
                if (stage >= 4) trace.append(fileReadGrantRangeReadLifecycleEvent(stage - 1));
                trace.append(fileReadGrantRangeReadResultEvent(stage - 1));
            }
            trace.append(fileReadGrantRangeStageEvent(stage, false));
        }
        String acceptance = allTrue("complete", "standardBundleMode", "rootRendered", "flowClientOwned", "fixtureCreated",
                "allStageStatusesObserved", "permissionAllowedObserved", "invalidRangesRejectedObserved", "grantRetainedAfterInvalidRanges",
                "maximumReadObserved", "tailReadObserved", "exactEofObserved", "beyondEofObserved", "nonzeroSeekObserved", "releaseObserved",
                "contentMatches", "perStageBalancedDrainObserved", "balancedDrainObserved", "resultStableAfterDrain", "errorFree",
                "securityScopedValueObserved", "windowRetained", "webViewRetained", "sameGrantFacadeObserved", "publicTokenHiddenObserved",
                "clientEventsObserved", "typedGrantApiObserved", "nativePointerObserved", "nativePointerTrustedObserved",
                "realOpenPanelObserved", "panelsAttachedObserved", "panelsVisibleObserved", "panelURLsVerified", "externalPanelSelection",
                "browserProgrammaticSetupObserved", "mainUidlRoundTripObserved", "opaqueRequestObserved", "opaqueResponseObserved",
                "opaquePushObserved", "gracefulCloseRequested");
        acceptance = acceptance.substring(0, acceptance.length() - 1) + """
                ,"mainWindowId":"main","mainSessionId":"flow-ipc-session","mainUiId":"main",
                "fixtureByteCount":65573,"maxReadBytes":65536,"securityScopedObserved":%s,
                "physicalInput":false,"sandboxEnforced":false,"recoveryGeneration":0,
                "stageCount":10,"panelCount":1,"nativePointerEventCount":10,"nativePointerTrustedEventCount":10,
                "observedStages":"%s","nativePointerStages":"%s","externalPanelSelectionStages":"file",
                "browserProgrammaticStages":"route-navigate","initialProcessIdentifier":121,"currentProcessIdentifier":121,
                "mainRequestBaseline":2,"mainResponseBaseline":2,"mainRequestCount":12,"mainResponseCount":12,
                "mainPushBaseline":0,"mainPushCount":1}
                """.formatted(scoped, String.join(",", fileReadGrantRangeStageNames()), String.join(",", fileReadGrantRangeStageNames()));
        trace.append(protocolPreservingStringWhitespace("recv", "flowFileReadGrantRange.frameworkAcceptance", acceptance));
        trace.append(rangeMainEvent(fileReadGrantWindowCloseRequestEvent())).append(rangeMainEvent(fileReadGrantWindowClosedEvent()));
        trace.append(fileReadGrantShutdownRequestEvent()).append(fileDialogOutcomesShutdownEvent());
        return fileReadGrantSecurity(trace.toString(), scoped);
    }

    private static List<String> fileReadGrantRangeStageNames() {
        return List.of("select", "negative", "zero", "oversized", "maximum", "tail", "eof", "beyond", "seek", "release");
    }

    private static int[][] fileReadGrantRangeRows() {
        return new int[][]{{-1, 16, 0, -1, -1, 0}, {0, 0, 0, -1, -1, 0}, {0, 65_537, 0, -1, -1, 0},
                {0, 65_536, 65_536, 0, 65_536, 0}, {65_536, 65_536, 37, 65_536, 65_573, 1},
                {65_573, 1, 0, 65_573, 65_573, 1}, {65_590, 16, 0, 65_590, 65_590, 1}, {257, 113, 113, 257, 370, 0}};
    }

    private static String fileReadGrantRangeOutcome(int readIndex) {
        return readIndex < 3 ? "INVALID_RANGE" : readIndex == 5 || readIndex == 6 ? "END_OF_FILE" : "DATA";
    }

    private static String rangeMainEvent(String event) {
        return event.replace("file-read-grant-secondary", "main").replace(FILE_READ_GRANT_SESSION, "flow-ipc-session")
                .replace("flowFileReadGrant.", "flowFileReadGrantRange.")
                .replace("fileGrant.release,window.close,window.open", "fileGrant.release,window.close");
    }

    private static String fileReadGrantRangeCommandEvent(int stage) {
        String name = stage == 0 ? "fileDialog.openReadGrant" : stage == 9 ? "fileGrant.release" : "fileGrant.read";
        String args = stage == 0 ? "{\"title\":\"Flow file read grant bounded ranges\"}" : "{\"grantId\":\"[redacted length=36]\"}";
        if (stage > 0 && stage < 9) {
            int[] row = fileReadGrantRangeRows()[stage - 1];
            args = "{\"grantId\":\"[redacted length=36]\",\"offset\":" + row[0] + ",\"maxBytes\":" + row[1] + "}";
        }
        return rangeMainEvent(fileReadGrantCommandEvent("range-command-" + stage, name, args));
    }

    private static String fileReadGrantRangeReadResultEvent(int readIndex) {
        int[] row = fileReadGrantRangeRows()[readIndex];
        String payload = readIndex < 3 ? """
                {"success":false,"command":"fileGrant.read","operation":"read-grant","grantUnavailable":false,
                "grantState":"active","errorCode":"invalid-read-range","error":"[redacted length=32]","maxReadBytes":65536,%s}
                """.formatted(fileReadGrantPermissionFields()) : """
                {"success":true,"command":"fileGrant.read","operation":"read-grant","grantUnavailable":false,
                "grantState":"active","bodyEncoding":"base64","bodyBytes":%d,"bodyRedacted":true,"bytesRead":%d,
                "offset":%d,"nextOffset":%d,"endOfFile":%s,"byteCount":65573,"maxReadBytes":65536,"pathExposed":false,%s}
                """.formatted(row[2], row[2], row[3], row[4], row[5] == 1, fileReadGrantPermissionFields());
        return rangeMainEvent(fileReadGrantResultEvent("range-command-" + (readIndex + 1), "fileGrant.read", payload));
    }

    private static String fileReadGrantRangeReadLifecycleEvent(int readIndex) {
        int[] row = fileReadGrantRangeRows()[readIndex];
        return protocolPreservingStringWhitespace("recv", "fileReadGrant.read", """
                {"diagnosticId":1,"offset":%d,"bytesRead":%d,"endOfFile":%s,"sidecarGeneration":1,"windowId":"main"}
                """.formatted(row[3], row[2], row[5] == 1));
    }

    private static String fileReadGrantRangeStageEvent(int stage, boolean scoped) {
        String payload = allTrue("complete", "client", "capabilityContextCaptured", "backgroundSessionAbsent", "publicTokenHidden",
                "permissionAllowed", "grantPresent", "filenameMatches", "balancedDrainObserved", "nativePointerObserved", "nativePointerTrustedObserved");
        payload = payload.substring(0, payload.length() - 1) + """
                ,"stage":"%s","processIdentifier":121,"windowId":"main","sessionId":"flow-ipc-session","uiId":"main",
                "change":1,"byteCount":65573,"maxReadBytes":65536,"securityScoped":%s,"requestCount":%d,"responseCount":%d,"pushCount":1
                """.formatted(fileReadGrantRangeStageNames().get(stage), scoped, stage + 3, stage + 3);
        if (stage == 0) payload += ",\"outcome\":\"SELECTED\",\"noPath\":true}";
        else if (stage == 9) payload += ",\"outcome\":\"RELEASED\",\"sameGrantFacade\":true,\"released\":true,\"securityScopeStopped\":" + scoped + "}";
        else {
            int[] row = fileReadGrantRangeRows()[stage - 1];
            payload += """
                    ,"outcome":"%s","sameGrantFacade":true,"grantActive":true,"requestedOffset":%d,"requestedMaxBytes":%d,
                    "bytesRead":%d,"offset":%d,"nextOffset":%d,"endOfFile":%s,"contentMatches":%s,"noContent":%s}
                    """.formatted(fileReadGrantRangeOutcome(stage - 1), row[0], row[1], row[2], row[3], row[4], row[5] == 1, stage >= 4, stage < 4);
        }
        return protocolPreservingStringWhitespace("recv", "flowFileReadGrantRange.stageObserved", payload);
    }

