    private static String validFileReadGrantReplayTrace(boolean oldScoped, boolean freshScoped) {
        String base = validFileReadGrantSidecarExitTrace(oldScoped, freshScoped);
        String freshPointer = fileReadGrantPointerEvent("recovered-select-first",
                "file-read-grant-secondary", FILE_READ_GRANT_SESSION, "file-read-grant-secondary");
        String postReadPointer = fileReadGrantPointerEvent("secondary-read-after-release",
                "file-read-grant-secondary", FILE_READ_GRANT_SESSION, "file-read-grant-secondary");
        String oldPhase = base.substring(0, base.indexOf(freshPointer))
                .replace(fileReadGrantManifestEvent(), fileReadGrantReplayManifestEvent())
                .replace("Flow file read grant explicit release", "Flow file read grant before recovery")
                .replace("secondary-select-first", "secondary-select-old")
                .replace("\"stage\":\"first\"", "\"stage\":\"old\"");
        String freshPhase = base.substring(base.indexOf(freshPointer), base.indexOf(postReadPointer))
                .replace("Flow file read grant explicit release", "Flow file read grant after recovery")
                .replace("recovered-select-first", "recovered-select-fresh")
                .replace("secondary-read-first", "secondary-fresh-read")
                .replace("secondary-release-first", "secondary-fresh-release")
                .replace("\"stage\":\"recovered\"", "\"stage\":\"fresh\"");
        StringBuilder trace = new StringBuilder(replayEvent(oldPhase).replace(replayEvent(fileReadGrantExitInjectionEvent()),
                fileReadGrantReplayBeforeFailureEvent(oldScoped) + replayEvent(fileReadGrantExitInjectionEvent())));
        for (String operation : List.of("read", "release")) {
            trace.append(replayEvent(fileReadGrantPointerEvent("recovered-old-" + operation,
                    "file-read-grant-secondary", FILE_READ_GRANT_SESSION, "file-read-grant-secondary")));
            trace.append(replayEvent(fileReadGrantGenerationTwo(fileReadGrantCommandEvent("replay-old-" + operation,
                    "fileGrant." + operation, "read".equals(operation) ? fileReadGrantReadArgs() : fileReadGrantReleaseArgs()))));
            trace.append(fileReadGrantReplayDeniedEvent(operation));
            trace.append(fileReadGrantReplayOldResultEvent(operation));
        }
        trace.append(replayEvent(freshPhase));
        trace.append(replayEvent(fileReadGrantPointerEvent("main-close-secondary", "main", "flow-ipc-session", "main")));
        trace.append(replayEvent(fileReadGrantWindowCloseRequestEvent()));
        trace.append(replayEvent(fileReadGrantWindowClosedEvent()));
        trace.append(fileReadGrantReplayAcceptanceEvent(oldScoped, freshScoped));
        trace.append(fileReadGrantForeignEvent(fileReadGrantWindowCloseRequestEvent()));
        trace.append(fileReadGrantForeignEvent(fileReadGrantWindowClosedEvent()));
        trace.append(fileReadGrantShutdownRequestEvent());
        trace.append(fileDialogOutcomesShutdownEvent());
        return trace.toString();
    }

    private static String replayEvent(String event) {
        return event.replace("file-read-grant-secondary", "file-read-grant-replay-secondary")
                .replace("flowFileReadGrant.", "flowFileReadGrantReplay.")
                .replace("active-file-read-grant", "stale-file-read-grant-replay");
    }

    private static String fileReadGrantReplayDeniedEvent(String operation) {
        return replayEvent(fileReadGrantGenerationTwo(
                fileReadGrantLifecycleEvent("fileReadGrant.accessDenied", 1, "sidecar-exit")))
                .replace("\"command\":\"fileGrant.read\"", "\"command\":\"fileGrant." + operation + "\"");
    }

    private static String fileReadGrantReplayOldResultEvent(String operation) {
        return replayEvent(fileReadGrantGenerationTwo(fileReadGrantUnavailableResultEvent()))
                .replace("file-grant-read-after-release", "replay-old-" + operation)
                .replace("fileGrant.read\"", "fileGrant." + operation + "\"")
                .replace("\"operation\":\"read-grant\"", "\"operation\":\"" + operation + "-grant\"");
    }

    private static String fileReadGrantReplayManifestEvent() {
        return protocolPreservingStringWhitespace("recv", "capabilityManifest", """
                {"path":"$APP/Contents/Resources/desktop-capabilities.json","loaded":true,"permissionMode":"manifest-enforced",
                "commandsByWindow":{"main":["window.close"],"file-read-grant-replay-secondary":["fileDialog.openReadGrant",
                "fileGrant.read","fileGrant.release","window.close","window.open"]},"parseError":""}
                """);
    }

    private static String fileReadGrantReplayBeforeFailureEvent(boolean oldScoped) {
        String payload = allTrue("complete", "handoffWritten", "handoffVerified", "handoffProtected",
                "preFailureBalancedDrainObserved", "windowRetained", "webViewRetained", "secondaryWindowRetained",
                "secondaryWebViewRetained", "ownerWindowsOpen");
        payload = withFalse(payload, "oldSecurityScoped").replace("\"oldSecurityScoped\":false", "\"oldSecurityScoped\":" + oldScoped);
        payload = withText(payload, "windowId", "file-read-grant-replay-secondary");
        payload = withText(payload, "sessionId", FILE_READ_GRANT_SESSION);
        payload = withText(payload, "uiId", "file-read-grant-replay-secondary");
        payload = withText(payload, "mainWindowId", "main");
        payload = withText(payload, "mainSessionId", "flow-ipc-session");
        payload = withText(payload, "mainUiId", "main");
        payload = withText(payload, "nativePointerStages", "main-open-secondary,secondary-select-old");
        payload = withNumber(payload, "nativePointerEventCount", 2);
        payload = withNumber(payload, "nativePointerTrustedEventCount", 2);
        payload = withNumber(payload, "producerProcessIdentifier", 121);
        payload = withNumber(payload, "currentProcessIdentifier", 121);
        payload = withNumber(payload, "oldSecondaryRequestBaseline", 2);
        payload = withNumber(payload, "oldSecondaryResponseBaseline", 2);
        payload = withNumber(payload, "oldSecondaryRequestCount", 3);
        payload = withNumber(payload, "oldSecondaryResponseCount", 3);
        payload = withNumber(payload, "mainRequestCount", 4);
        payload = withNumber(payload, "mainResponseCount", 4);
        return protocolPreservingStringWhitespace("recv", "flowFileReadGrantReplay.beforeFailureObserved", payload);
    }

    private static String fileReadGrantReplayAcceptanceEvent(boolean oldScoped, boolean freshScoped) {
        String payload = allTrue("complete", "standardBundleMode", "rootRendered", "flowClientOwned",
                "secondaryRenderingObserved", "fixtureCreated", "realOpenPanelObserved", "panelsAttachedObserved",
                "panelsVisibleObserved", "panelURLsVerified", "externalPanelSelection", "scopeIsolatedObserved",
                "mainUidlRoundTripObserved", "secondaryUidlRoundTripObserved", "opaqueRequestObserved", "opaqueResponseObserved",
                "secondaryContextRemoved", "secondaryWindowClosedObserved", "gracefulCloseRequested", "preFailureBalancedDrainObserved",
                "liveBalancedDrainObserved", "balancedDrainObserved", "resultStableAfterDrain", "errorFree",
                "oldSelectionStatusObserved", "oldReadStatusObserved", "oldReleaseStatusObserved", "freshSelectionStatusObserved",
                "freshReadStatusObserved", "freshReleaseStatusObserved", "contentMatches", "securityScopedValueObserved",
                "nativePointerObserved", "nativePointerTrustedObserved", "browserProgrammaticSetupObserved", "windowRetained",
                "webViewRetained", "secondaryWindowRetained", "secondaryWebViewRetained", "liveOwnerRetainedThroughRelease",
                "processReplaced", "recoveredStateResetObserved", "handoffWrittenObserved", "handoffVerifiedObserved",
                "handoffProtectedObserved", "handoffRemovedObserved", "handoffRetainedThroughOldReleaseObserved",
                "sameOldTokenUsedObserved", "oldTokenUnchangedObserved", "freshTokenDistinctObserved", "sameFreshTokenUsedObserved",
                "permissionAllowedObserved", "oldNoContentObserved", "recoveredProcessObserved");
        payload = withFalse(payload, "physicalInput", "sandboxEnforced", "oldSecurityScoped", "freshSecurityScoped")
                .replace("\"oldSecurityScoped\":false", "\"oldSecurityScoped\":" + oldScoped)
                .replace("\"freshSecurityScoped\":false", "\"freshSecurityScoped\":" + freshScoped);
        payload = withText(payload, "oldSelectionOutcome", "SELECTED");
        payload = withText(payload, "oldReadOutcome", "UNAVAILABLE");
        payload = withText(payload, "oldReleaseOutcome", "UNAVAILABLE");
        payload = withText(payload, "freshSelectionOutcome", "SELECTED");
        payload = withText(payload, "freshReadOutcome", "DATA");
        payload = withText(payload, "freshReleaseOutcome", "RELEASED");
        payload = withText(payload, "nativePointerStages", "main-open-secondary,secondary-select-old,recovered-old-read,"
                + "recovered-old-release,recovered-select-fresh,secondary-fresh-read,secondary-fresh-release,main-close-secondary");
        payload = withText(payload, "externalPanelSelectionStages", "old,fresh");
        payload = withText(payload, "browserProgrammaticStages", "route-navigate,recovered-route-navigate");
        payload = fileReadGrantShutdownScopes(payload).replace("file-read-grant-secondary", "file-read-grant-replay-secondary");
        payload = withNumber(payload, "fixtureByteCount", 48);
        payload = withNumber(payload, "freshReadBytes", 19);
        payload = withNumber(payload, "panelCount", 2);
        payload = withNumber(payload, "nativePointerEventCount", 8);
        payload = withNumber(payload, "nativePointerTrustedEventCount", 8);
        for (String field : List.of("initialProcessIdentifier", "failedProcessIdentifier", "handoffProducerProcessIdentifier")) {
            payload = withNumber(payload, field, 121);
        }
        for (String field : List.of("recoveredProcessIdentifier", "restoredCurrentProcessIdentifier")) {
            payload = withNumber(payload, field, 222);
        }
        payload = withNumber(payload, "recoveryGeneration", 1);
        for (String scope : List.of("oldSecondary", "main", "secondary")) {
            payload = withNumber(payload, scope + "RequestBaseline", 2);
            payload = withNumber(payload, scope + "ResponseBaseline", 2);
            payload = withNumber(payload, scope + "RequestCount", "secondary".equals(scope) ? 7 : 3);
            payload = withNumber(payload, scope + "ResponseCount", "secondary".equals(scope) ? 7 : 3);
        }
        return protocolPreservingStringWhitespace("recv", "flowFileReadGrantReplay.frameworkAcceptance", payload);
    }

    private static String validFileReadGrantIsolationTrace(boolean scoped) {
        String base = validFileReadGrantTrace();
        String readPointer = fileReadGrantPointerEvent("secondary-read-first",
                "file-read-grant-secondary", FILE_READ_GRANT_SESSION, "file-read-grant-secondary");
        String selectPointer = fileReadGrantPointerEvent("secondary-select-first",
                "file-read-grant-secondary", FILE_READ_GRANT_SESSION, "file-read-grant-secondary");
        String selection = base.substring(0, base.indexOf(readPointer))
                .replace(fileReadGrantManifestEvent(), fileReadGrantIsolationManifestEvent())
                .replace(protocol("recv", "window.create", "{\"windowId\":\"main\"}"),
                        mainCloseRecoveryMainCreateEvent() + fileReadGrantLoadedEvent("main", 0))
                .replace(selectPointer, fileReadGrantSecondaryCreateEvent()
                        + fileReadGrantLoadedEvent("file-read-grant-secondary", 0) + selectPointer)
                .replace("secondary-select-first", "secondary-select")
                .replace("\"stage\":\"first\"", "\"stage\":\"owner\"")
                .replace("Flow file read grant explicit release", "Flow file read grant owner isolation");
        StringBuilder trace = new StringBuilder(isolationEvent(selection));
        for (String operation : List.of("read", "release")) {
            String command = "fileGrant." + operation;
            trace.append(isolationEvent(fileReadGrantPointerEvent("main-foreign-" + operation,
                    "main", "flow-ipc-session", "main")));
            trace.append(fileReadGrantForeignEvent(fileReadGrantCommandEvent("foreign-" + operation,
                    command, "read".equals(operation) ? fileReadGrantReadArgs() : fileReadGrantReleaseArgs())));
            trace.append(fileReadGrantForeignDeniedEvent(command));
            trace.append(fileReadGrantForeignResultEvent(command));
        }
        trace.append(isolationEvent(fileReadGrantPointerEvent("secondary-owner-read",
                "file-read-grant-secondary", FILE_READ_GRANT_SESSION, "file-read-grant-secondary")));
        trace.append(isolationEvent(fileReadGrantCommandEvent("file-grant-read-first", "fileGrant.read", fileReadGrantReadArgs())));
        trace.append(isolationEvent(fileReadGrantLifecycleEvent("fileReadGrant.read", 1, "")));
        trace.append(isolationEvent(fileReadGrantDataResultEvent()));
        trace.append(isolationEvent(fileReadGrantPointerEvent("secondary-owner-release",
                "file-read-grant-secondary", FILE_READ_GRANT_SESSION, "file-read-grant-secondary")));
        trace.append(isolationEvent(fileReadGrantCommandEvent("file-grant-release-first", "fileGrant.release", fileReadGrantReleaseArgs())));
        trace.append(isolationEvent(fileReadGrantLifecycleEvent("fileReadGrant.releaseScheduled", 1, "released")));
        trace.append(isolationEvent(fileReadGrantLifecycleEvent("fileReadGrant.closed", 1, "released")));
        trace.append(isolationEvent(fileReadGrantReleaseResultEvent()));
        trace.append(isolationEvent(fileReadGrantPointerEvent("main-close-secondary", "main", "flow-ipc-session", "main")));
        trace.append(isolationEvent(fileReadGrantWindowCloseRequestEvent()));
        trace.append(isolationEvent(fileReadGrantWindowClosedEvent()));
        trace.append(fileReadGrantIsolationAcceptanceEvent(false));
        trace.append(fileReadGrantForeignEvent(fileReadGrantWindowCloseRequestEvent()));
        trace.append(fileReadGrantForeignEvent(fileReadGrantWindowClosedEvent()));
        trace.append(fileReadGrantShutdownRequestEvent());
        trace.append(fileDialogOutcomesShutdownEvent());
        return fileReadGrantSecurity(trace.toString(), scoped)
                .replace("\"securityScopedObserved\":false", "\"securityScopedObserved\":" + scoped);
    }

    private static String isolationEvent(String event) {
        return event.replace("file-read-grant-secondary", "file-read-grant-isolation-secondary")
                .replace("flowFileReadGrant.", "flowFileReadGrantIsolation.");
    }

    private static String fileReadGrantForeignEvent(String event) {
        return event.replace("file-read-grant-secondary", "main")
                .replace(FILE_READ_GRANT_SESSION, "flow-ipc-session")
                .replace("fileDialog.openReadGrant,fileGrant.read,fileGrant.release,window.close,window.open",
                        "fileGrant.read,fileGrant.release,window.close");
    }

    private static String fileReadGrantReadArgs() {
        return "{\"grantId\":\"[redacted length=36]\",\"offset\":0,\"maxBytes\":19}";
    }

    private static String fileReadGrantReleaseArgs() {
        return "{\"grantId\":\"[redacted length=36]\"}";
    }

    private static String fileReadGrantForeignResultEvent(String command) {
        String operation = "fileGrant.read".equals(command) ? "read" : "release";
        return fileReadGrantForeignEvent(fileReadGrantUnavailableResultEvent())
                .replace("file-grant-read-after-release", "foreign-" + operation)
                .replace("fileGrant.read\"", command + "\"")
                .replace("\"operation\":\"read-grant\"", "\"operation\":\"" + operation + "-grant\"");
    }

    private static String fileReadGrantForeignDeniedEvent(String command) {
        return protocolPreservingStringWhitespace("recv", "fileReadGrant.accessDenied", """
                {"command":"%s","reason":"unknown-token","sidecarGeneration":1,
                "windowId":"main","sessionId":"flow-ipc-session","uiId":"main"}
                """.formatted(command));
    }

    private static String fileReadGrantIsolationManifestEvent() {
        return protocolPreservingStringWhitespace("recv", "capabilityManifest", """
                {"path":"$APP/Contents/Resources/desktop-capabilities.json",
                "loaded":true,"permissionMode":"manifest-enforced",
                "commandsByWindow":{"main":["fileGrant.read","fileGrant.release","window.close"],
                "file-read-grant-isolation-secondary":["fileDialog.openReadGrant","fileGrant.read",
                "fileGrant.release","window.close","window.open"]},"parseError":""}
                """);
    }

    private static String fileReadGrantIsolationAcceptanceEvent(boolean scoped) {
        String payload = allTrue("complete", "standardBundleMode", "rootRendered", "flowClientOwned",
                "fixtureCreated", "realOpenPanelObserved", "panelsAttachedObserved",
                "panelsVisibleObserved", "panelURLsVerified", "externalPanelSelection", "scopeIsolatedObserved",
                "mainUidlRoundTripObserved", "secondaryUidlRoundTripObserved", "opaqueRequestObserved",
                "opaqueResponseObserved", "secondaryContextRemoved", "secondaryWindowClosedObserved",
                "gracefulCloseRequested", "balancedDrainObserved", "resultStableAfterDrain", "errorFree",
                "selectionStatusObserved", "foreignReadStatusObserved", "foreignReleaseStatusObserved",
                "ownerReadStatusObserved", "ownerReleaseStatusObserved", "contentMatches", "securityScopedValueObserved",
                "nativePointerObserved", "nativePointerTrustedObserved", "browserProgrammaticSetupObserved",
                "windowRetained", "webViewRetained", "secondaryWindowRetained", "secondaryWebViewRetained",
                "sameTokenUsedObserved", "ownerTokenUnchangedObserved", "permissionAllowedObserved",
                "foreignNoContentObserved", "liveOwnerRetainedThroughRelease", "liveBalancedDrainObserved", "secondaryRenderingObserved");
        payload = withFalse(payload, "physicalInput", "sandboxEnforced", "securityScopedObserved");
        payload = payload.replace("\"securityScopedObserved\":false", "\"securityScopedObserved\":" + scoped);
        payload = withText(payload, "selectionOutcome", "SELECTED");
        payload = withText(payload, "foreignReadOutcome", "UNAVAILABLE");
        payload = withText(payload, "foreignReleaseOutcome", "UNAVAILABLE");
        payload = withText(payload, "ownerReadOutcome", "DATA");
        payload = withText(payload, "ownerReleaseOutcome", "RELEASED");
        payload = withText(payload, "nativePointerStages", "main-open-secondary,secondary-select,main-foreign-read,"
                + "main-foreign-release,secondary-owner-read,secondary-owner-release,main-close-secondary");
        payload = withText(payload, "externalPanelSelectionStages", "owner");
        payload = withText(payload, "browserProgrammaticStages", "route-navigate");
        payload = fileReadGrantShutdownScopes(payload).replace("file-read-grant-secondary", "file-read-grant-isolation-secondary");
        payload = withNumber(payload, "fixtureByteCount", 48);
        payload = withNumber(payload, "ownerReadBytes", 19);
        payload = withNumber(payload, "panelCount", 1);
        payload = withNumber(payload, "nativePointerEventCount", 7);
        payload = withNumber(payload, "nativePointerTrustedEventCount", 7);
        payload = withNumber(payload, "initialProcessIdentifier", 121);
        payload = withNumber(payload, "currentProcessIdentifier", 121);
        payload = withNumber(payload, "recoveryGeneration", 0);
        for (String owner : List.of("main", "secondary")) {
            payload = withNumber(payload, owner + "RequestBaseline", 2);
            payload = withNumber(payload, owner + "ResponseBaseline", 2);
            payload = withNumber(payload, owner + "RequestCount", "main".equals(owner) ? 6 : 5);
            payload = withNumber(payload, owner + "ResponseCount", "main".equals(owner) ? 6 : 5);
        }
        return protocolPreservingStringWhitespace("recv", "flowFileReadGrantIsolation.frameworkAcceptance", payload);
    }

    private static String validFileReadGrantHostShutdownTrace(boolean scoped) {
        String base = validFileReadGrantTrace();
        String readPointer = fileReadGrantPointerEvent("secondary-read-first",
                "file-read-grant-secondary", FILE_READ_GRANT_SESSION, "file-read-grant-secondary");
        String selectPointer = fileReadGrantPointerEvent("secondary-select-first",
                "file-read-grant-secondary", FILE_READ_GRANT_SESSION, "file-read-grant-secondary");
        String selection = base.substring(0, base.indexOf(readPointer))
                .replace(protocol("recv", "window.create", "{\"windowId\":\"main\"}"),
                        mainCloseRecoveryMainCreateEvent() + fileReadGrantLoadedEvent("main", 0))
                .replace(selectPointer, fileReadGrantSecondaryCreateEvent()
                        + fileReadGrantLoadedEvent("file-read-grant-secondary", 0) + selectPointer);
        return fileReadGrantSecurity(selection, scoped)
                + fileReadGrantHostShutdownPreparedEvent(scoped)
                + fileReadGrantSecurity(fileReadGrantLifecycleEvent(
                        "fileReadGrant.invalidated", 1, "host-shutdown"), scoped)
                + fileReadGrantDrainStartedEvent()
                + fileReadGrantSecurity(fileReadGrantLifecycleEvent(
                        "fileReadGrant.closed", 1, "host-shutdown"), scoped)
                + fileReadGrantDrainCompletedEvent()
                + fileReadGrantShutdownRequestEvent()
                + normalShutdownSidecarExitEvent()
                + fileDialogOutcomesShutdownEvent()
                + fileReadGrantHostShutdownObservedEvent();
    }

    private static String fileReadGrantHostShutdownPreparedEvent(boolean scoped) {
        String payload = allTrue("complete", "standardBundleMode", "rootRendered", "flowClientOwned",
                "fixtureCreated", "firstSelectionStatusObserved", "securityScopedValueObserved",
                "windowRetained", "webViewRetained", "secondaryWindowRetained", "secondaryWebViewRetained",
                "realOpenPanelObserved", "panelsAttachedObserved", "panelsVisibleObserved", "panelURLsVerified",
                "externalPanelSelection", "nativePointerObserved", "nativePointerTrustedObserved",
                "browserProgrammaticSetupObserved", "operationsPending", "ownerWindowsOpen",
                "balancedDrainObserved", "errorFree", "scopeIsolatedObserved", "mainUidlRoundTripObserved",
                "secondaryUidlRoundTripObserved", "opaqueRequestObserved", "opaqueResponseObserved",
                "resultStableAfterDrain", "acceptanceQuitMenuInstalled");
        payload = withFalse(payload, "physicalInput", "sandboxEnforced", "firstSecurityScoped");
        payload = payload.replace("\"firstSecurityScoped\":false", "\"firstSecurityScoped\":" + scoped);
        payload = withText(payload, "firstSelectionOutcome", "SELECTED");
        payload = withText(payload, "nativePointerStages", "main-open-secondary,secondary-select-first");
        payload = withText(payload, "externalPanelSelectionStages", "first");
        payload = withText(payload, "browserProgrammaticStages", "route-navigate");
        payload = fileReadGrantShutdownScopes(payload);
        payload = withNumber(payload, "fixtureByteCount", 48);
        payload = withNumber(payload, "panelCount", 1);
        payload = withNumber(payload, "nativePointerEventCount", 2);
        payload = withNumber(payload, "nativePointerTrustedEventCount", 2);
        payload = withNumber(payload, "initialProcessIdentifier", 121);
        payload = withNumber(payload, "recoveryGeneration", 0);
        for (String owner : List.of("main", "secondary")) {
            payload = withNumber(payload, owner + "RequestBaseline", 2);
            payload = withNumber(payload, owner + "ResponseBaseline", 2);
            payload = withNumber(payload, owner + "RequestCount", 3);
            payload = withNumber(payload, owner + "ResponseCount", 3);
        }
        return protocolPreservingStringWhitespace("recv", "flowFileReadGrant.hostShutdownPrepared", payload);
    }

    private static String fileReadGrantHostShutdownObservedEvent() {
        String payload = allTrue("complete", "preparedObserved", "ownerWindowsOpen",
                "windowRetained", "webViewRetained", "secondaryWindowRetained", "secondaryWebViewRetained",
                "externalTerminationExpected", "originalSidecarAbsent");
        payload = withFalse(payload, "physicalInput");
        payload = withText(payload, "terminationSource", "applicationWillTerminate");
        payload = fileReadGrantShutdownScopes(payload);
        payload = withNumber(payload, "initialProcessIdentifier", 121);
        payload = withNumber(payload, "currentProcessIdentifier", 0);
        payload = withNumber(payload, "recoveryGeneration", 0);
        return protocolPreservingStringWhitespace("recv", "flowFileReadGrant.hostShutdownObserved", payload);
    }

    private static String fileReadGrantShutdownScopes(String payload) {
        payload = withText(payload, "mainWindowId", "main");
        payload = withText(payload, "mainSessionId", "flow-ipc-session");
        payload = withText(payload, "mainUiId", "main");
        payload = withText(payload, "secondaryWindowId", "file-read-grant-secondary");
        payload = withText(payload, "secondarySessionId", FILE_READ_GRANT_SESSION);
        return withText(payload, "secondaryUiId", "file-read-grant-secondary");
    }

    private static String fileReadGrantPostShutdownWindowTeardown(String window) {
        String session = "main".equals(window) ? "flow-ipc-session" : FILE_READ_GRANT_SESSION;
        return protocol("recv", "window.closeRequested", """
                {"label":"%s","windowId":"%s","sessionId":"%s","uiId":"%s"}
                """.formatted(window, window, session, window))
                + protocol("recv", "windowClosedDropped", """
                {"reason":"sidecar-lifecycle-unavailable","windowId":"%s","sessionId":"%s","uiId":"%s"}
                """.formatted(window, session, window));
    }

    private static String fileReadGrantDrainStartedEvent() {
        return protocol("recv", "host.nativeResourceDrainStarted", "{\"pendingCount\":1,\"timeoutSeconds\":2}");
    }

    private static String fileReadGrantDrainCompletedEvent() {
        return protocol("recv", "host.nativeResourceDrainCompleted",
                "{\"drained\":true,\"pendingCount\":0,\"failureCount\":0}");
    }

    private static String fileReadGrantShutdownRequestEvent() {
        return protocol("send", "shutdown",
                "{\"target\":\"java-sidecar\",\"transport\":\"flow-ipc\",\"reason\":\"host-terminate\"}");
    }

    private static String validFileReadGrantSidecarExitTrace(
            boolean oldSecurityScoped, boolean freshSecurityScoped) {
        String base = validFileReadGrantTrace();
        String selectPointer = fileReadGrantPointerEvent(
                "secondary-select-first", "file-read-grant-secondary",
                FILE_READ_GRANT_SESSION, "file-read-grant-secondary");
        String readPointer = fileReadGrantPointerEvent(
                "secondary-read-first", "file-read-grant-secondary",
                FILE_READ_GRANT_SESSION, "file-read-grant-secondary");
        String secondPointer = fileReadGrantPointerEvent(
                "secondary-select-second", "file-read-grant-secondary",
                FILE_READ_GRANT_SESSION, "file-read-grant-secondary");
        String oldSelection = base.substring(0, base.indexOf(readPointer))
                .replace(protocol("recv", "window.create",
                                "{\"windowId\":\"main\"}"),
                        mainCloseRecoveryMainCreateEvent()
                                + fileReadGrantLoadedEvent("main", 0))
                .replace(selectPointer,
                        fileReadGrantSecondaryCreateEvent()
                                + fileReadGrantLoadedEvent(
                                "file-read-grant-secondary", 0)
                                + selectPointer);
        String freshAccess = fileReadGrantGenerationTwo(
                base.substring(base.indexOf(selectPointer), base.indexOf(secondPointer))
                        .replace("\"stage\":\"secondary-select-first\"",
                                "\"stage\":\"recovered-select-first\"")
                        .replace("\"stage\":\"first\"",
                                "\"stage\":\"recovered\"")
                        .replace("\"diagnosticId\":1", "\"diagnosticId\":2"));
        String oldCleanup = fileReadGrantLifecycleEvent(
                "fileReadGrant.invalidated", 1, "sidecar-exit")
                + fileReadGrantLifecycleEvent(
                "fileReadGrant.closed", 1, "sidecar-exit");
        return fileReadGrantSecurity(oldSelection, oldSecurityScoped)
                + fileReadGrantExitInjectionEvent()
                + fileReadGrantSidecarExitEvent()
                + fileReadGrantSecurity(oldCleanup, oldSecurityScoped)
                + fileReadGrantRecoveryScheduledEvent()
                + protocol("send", "sidecar.recoveryStarted",
                "{\"attempt\":1,\"previousProcessIdentifier\":121}")
                + protocol("send", "launch.sidecar",
                "{\"generation\":2,\"transport\":\"flow-ipc\"}")
                + protocol("recv", "sidecar.started",
                "{\"generation\":2,\"processIdentifier\":222,"
                        + "\"transport\":\"flow-ipc\"}")
                + capabilityGenerationReadyEvent(2)
                + fileReadGrantRecoveryReadyEvent()
                + fileReadGrantLoadedEvent("main", 1)
                + fileReadGrantLoadedEvent("file-read-grant-secondary", 1)
                + fileReadGrantSecurity(freshAccess, freshSecurityScoped)
                + fileReadGrantPointerEvent(
                "main-close-secondary", "main", "flow-ipc-session", "main")
                + fileReadGrantWindowCloseRequestEvent()
                + fileReadGrantWindowClosedEvent()
                + fileReadGrantSidecarExitAcceptanceEvent(
                oldSecurityScoped, freshSecurityScoped)
                + protocol("recv", "shutdown.sidecar", "{\"mode\":\"graceful\"}");
    }

    private static String fileReadGrantGenerationTwo(String events) {
        return events.replace("\"sidecarGeneration\":1",
                "\"sidecarGeneration\":2");
    }

    private static String fileReadGrantSecurity(String events, boolean scoped) {
        return events.replace("\"securityScoped\":false",
                        "\"securityScoped\":" + scoped)
                .replace("\"securityScopeStopped\":false",
                        "\"securityScopeStopped\":" + scoped);
    }

