    private static String fileReadGrantLoadedEvent(
            String windowId, int recoveryGeneration) {
        String sessionId = "main".equals(windowId)
                ? "flow-ipc-session" : FILE_READ_GRANT_SESSION;
        return protocolPreservingStringWhitespace("recv", "webview.loaded", """
                {"label":"%s","windowId":"%s","sessionId":"%s","uiId":"%s",
                "recoveryGeneration":%d,"title":"Flow file read grant",
                "windowSharingType":1}
                """.formatted(
                windowId, windowId, sessionId, windowId, recoveryGeneration));
    }

    private static String fileReadGrantSidecarExitAcceptanceEvent(
            boolean oldSecurityScoped, boolean freshSecurityScoped) {
        String acceptance = fileReadGrantAcceptancePayload()
                .replace("\"recoveryGeneration\":0", "\"recoveryGeneration\":1")
                .replace("\"mainRequestCount\":4", "\"mainRequestCount\":3")
                .replace("\"mainResponseCount\":4", "\"mainResponseCount\":3")
                .replace("\"externalPanelSelectionStages\":\"first,second\"",
                        "\"externalPanelSelectionStages\":\"first,recovered\"")
                .replace("\"browserProgrammaticStages\":\"route-navigate\"",
                        "\"browserProgrammaticStages\":"
                                + "\"route-navigate,recovered-route-navigate\"")
                .replace("main-open-secondary,secondary-select-first,"
                                + "secondary-read-first,secondary-release-first,"
                                + "secondary-read-after-release,secondary-select-second,"
                                + "main-close-secondary",
                        "main-open-secondary,secondary-select-first,recovered-select-first,"
                                + "secondary-read-first,secondary-release-first,"
                                + "secondary-read-after-release,main-close-secondary")
                .replace("\"securityScopedObserved\":false",
                        "\"securityScopedObserved\":" + oldSecurityScoped)
                .replace("\"firstSecurityScoped\":false",
                        "\"firstSecurityScoped\":" + oldSecurityScoped)
                .replace("\"secondSecurityScoped\":false",
                        "\"secondSecurityScoped\":" + freshSecurityScoped);
        String retention = allTrue(
                "windowRetained", "webViewRetained",
                "secondaryWindowRetained", "secondaryWebViewRetained",
                "processReplaced", "recoveredStateResetObserved");
        acceptance = acceptance.substring(0, acceptance.length() - 1)
                + "," + retention.substring(1);
        acceptance = withNumber(acceptance, "initialProcessIdentifier", 121);
        acceptance = withNumber(acceptance, "failedProcessIdentifier", 121);
        acceptance = withNumber(acceptance, "recoveredProcessIdentifier", 222);
        acceptance = withNumber(acceptance, "oldSecondaryRequestBaseline", 2);
        acceptance = withNumber(acceptance, "oldSecondaryResponseBaseline", 2);
        acceptance = withNumber(acceptance, "oldSecondaryRequestCount", 3);
        acceptance = withNumber(acceptance, "oldSecondaryResponseCount", 3);
        return protocolPreservingStringWhitespace(
                "recv", "flowFileReadGrant.sidecarExitAcceptance", acceptance);
    }

