    private static String validClipboardOutcomesTrace() {
        StringBuilder trace = new StringBuilder();
        trace.append(protocol(
                "recv", "launch", "{\"transport\":\"flow-ipc\"}"));
        trace.append(capabilityPermissionManifest()
                .replace("permission-secondary", "clipboard-outcomes-secondary"));
        trace.append(protocol(
                "send", "launch.sidecar",
                "{\"generation\":1,\"transport\":\"flow-ipc\"}"));
        trace.append(protocol(
                "recv", "sidecar.started",
                "{\"generation\":1,\"processIdentifier\":111,"
                        + "\"transport\":\"flow-ipc\"}"));
        trace.append(capabilityGenerationReadyEvent(1));
        trace.append(protocol(
                "recv", "window.create", "{\"windowId\":\"main\"}"));
        trace.append(protocol(
                "recv", "standardBundleReady",
                "{\"requestTransport\":\"opaque-http-stream-ipc\"}"));
        trace.append(protocol(
                "recv", "standardBundleResource",
                "{\"path\":\"/VAADIN/build/FlowClient-clipboard.js\"}"));
        trace.append(protocol(
                "recv", "webview.firstMeaningfulPaint", "{}"));
        for (String requestId : new String[]{
                "clipboard-bootstrap", "clipboard-uidl"}) {
            trace.append(protocol(
                    "send", "opaqueHttpStreamOpen",
                    "{\"requestId\":\"" + requestId + "\"}"));
            trace.append(protocol(
                    "recv", "opaqueHttpStreamResponse",
                    "{\"requestId\":\"" + requestId
                            + "\",\"status\":200}"));
            trace.append(protocol(
                    "recv", "opaqueHttpStreamResponseEnd",
                    "{\"requestId\":\"" + requestId + "\"}"));
        }
        trace.append(protocol(
                "recv", "opaquePushConnected",
                "{\"windowId\":\"main\","
                        + "\"sessionId\":\"flow-ipc-session\","
                        + "\"uiId\":\"main\"}"));
        trace.append(clipboardOutcomesPointerEvent(
                "main-no-text", "main", "flow-ipc-session", "main"));
        trace.append(clipboardNoTextCommandEvent());
        trace.append(clipboardNoTextResultEvent());
        trace.append(clipboardOutcomesPointerEvent(
                "main-empty", "main", "flow-ipc-session", "main"));
        trace.append(clipboardEmptyWriteCommandEvent());
        trace.append(clipboardEmptyWriteResultEvent());
        trace.append(clipboardEmptyReadCommandEvent());
        trace.append(clipboardEmptyReadResultEvent());
        trace.append(clipboardOutcomesPointerEvent(
                "secondary-denied", "clipboard-outcomes-secondary",
                CLIPBOARD_OUTCOMES_SESSION,
                "clipboard-outcomes-secondary"));
        trace.append(clipboardDeniedWriteCommandEvent());
        trace.append(clipboardDeniedWriteResultEvent());
        trace.append(clipboardDeniedReadCommandEvent());
        trace.append(clipboardDeniedReadResultEvent());
        trace.append(clipboardOutcomesAcceptanceEvent());
        trace.append(clipboardOutcomesShutdownEvent());
        return trace.toString();
    }

