    private static String clipboardOutcomesCommandEvent(
            String commandId,
            String command,
            String windowId,
            String sessionId,
            String uiId,
            int textLength) {
        String args = textLength < 0
                ? "{}"
                : "{\"textLength\":" + textLength
                + ",\"textRedacted\":true}";
        return protocolPreservingStringWhitespace("recv", "command", """
                {"source":"java-sidecar","transport":"flow-ipc",
                "sidecarGeneration":1,
                "envelope":{"version":1,"type":"command",
                "id":"%s","correlationId":"%s",
                "sessionId":"%s","uiId":"%s",
                "windowId":"%s","route":"",
                "payload":{"command":"%s","args":%s},
                "error":null,"timestamp":1}}
                """.formatted(
                commandId, commandId, sessionId, uiId, windowId,
                command, args));
    }

