    private static String clipboardDeniedResultEvent(
            String commandId,
            String command,
            int timestamp) {
        return protocolPreservingStringWhitespace(
                "send", "capabilityResult", """
                {"target":"java-sidecar","transport":"flow-ipc",
                "command":"%s","sidecarGeneration":1,
                "envelope":{"version":1,"type":"capabilityResult",
                "id":"capability-%s","correlationId":"%s",
                "sessionId":"%s",
                "uiId":"clipboard-outcomes-secondary",
                "windowId":"clipboard-outcomes-secondary","route":"",
                "payload":{"success":false,"command":"%s",
                "error":"Command not allowed by desktop-capabilities.json",
                "permissionMode":"manifest-enforced",
                "permissionDecision":"denied",
                "permissionReason":"manifest-denied",
                "permissionScope":"window:clipboard-outcomes-secondary",
                "permissionManifestLoaded":true,
                "permissionManifestPath":"$APP/Contents/Resources/desktop-capabilities.json",
                "permissionManifestCommands":"window.close,window.open"},
                "error":null,"timestamp":%d}}
                """.formatted(
                command, commandId, commandId,
                CLIPBOARD_OUTCOMES_SESSION, command, timestamp));
    }

