    private static String capabilityContextReopenAcceptanceEvent() {
        String acceptance = allTrue(
                "complete", "standardBundleMode", "rootRendered",
                "flowClientOwned", "samePublicId", "differentSession",
                "threeDistinctSessionsObserved",
                "threeDistinctWindowIdentitiesObserved",
                "threeDistinctWebViewIdentitiesObserved",
                "firstContextReleasedObserved",
                "firstWindowHiddenObserved",
                "reopenedContextReleasedObserved",
                "reopenedWindowHiddenObserved",
                "windowIdentityRecreatedObserved",
                "webViewIdentityRecreatedObserved",
                "firstCaptureSuccess", "retiredBeforeInvalidated",
                "freshSuccess", "retiredAfterInvalidated",
                "firstBeforeInvalidated", "reopenedBeforeInvalidated",
                "thirdFreshSuccess", "firstAfterInvalidated",
                "reopenedAfterInvalidated",
                "backgroundSessionAbsent",
                "firstBackgroundSessionAbsent",
                "reopenedBackgroundSessionAbsent",
                "thirdBackgroundSessionAbsent",
                "mainWindowRetainedObserved",
                "mainWebViewRetainedObserved",
                "mainProcessRetainedObserved",
                "nativePointerObserved", "nativePointerTrustedObserved",
                "browserProgrammaticSetupObserved",
                "balancedDrainObserved", "resultStableAfterDrain",
                "errorFree");
        acceptance = withText(
                acceptance, "firstWindowId", "capability-reopen-secondary");
        acceptance = withText(
                acceptance,
                "firstSessionId",
                CAPABILITY_CONTEXT_REOPEN_FIRST_SESSION);
        acceptance = withText(
                acceptance, "firstUiId", "capability-reopen-secondary");
        acceptance = withText(
                acceptance,
                "reopenedWindowId",
                "capability-reopen-secondary");
        acceptance = withText(
                acceptance,
                "reopenedSessionId",
                CAPABILITY_CONTEXT_REOPEN_SECOND_SESSION);
        acceptance = withText(
                acceptance, "reopenedUiId", "capability-reopen-secondary");
        acceptance = withText(
                acceptance,
                "thirdWindowId",
                "capability-reopen-secondary");
        acceptance = withText(
                acceptance,
                "thirdSessionId",
                CAPABILITY_CONTEXT_REOPEN_THIRD_SESSION);
        acceptance = withText(
                acceptance, "thirdUiId", "capability-reopen-secondary");
        acceptance = withText(
                acceptance, "retiredBeforeReason", "owner-window-closed");
        acceptance = withText(
                acceptance, "retiredAfterReason", "owner-window-closed");
        acceptance = withText(
                acceptance, "firstBeforeReason", "owner-window-closed");
        acceptance = withText(
                acceptance, "reopenedBeforeReason", "owner-window-closed");
        acceptance = withText(
                acceptance, "firstAfterReason", "owner-window-closed");
        acceptance = withText(
                acceptance, "reopenedAfterReason", "owner-window-closed");
        acceptance = withText(
                acceptance,
                "firstTitle",
                "Flow capability context incarnation A");
        acceptance = withText(
                acceptance,
                "reopenedTitle",
                "Flow capability context incarnation B");
        acceptance = withText(
                acceptance,
                "thirdTitle",
                "Flow capability context incarnation C");
        acceptance = withText(
                acceptance,
                "firstStatus",
                "Capability context reopen first: firstSuccess=true "
                        + "capabilityContextCaptured=true "
                        + "backgroundSessionAbsent=true client=true change=1");
        acceptance = withText(
                acceptance,
                "thirdStatus",
                "Capability context reopen third: "
                        + "firstBeforeInvalidated=true "
                        + "firstBeforeReason=owner-window-closed "
                        + "reopenedBeforeInvalidated=true "
                        + "reopenedBeforeReason=owner-window-closed "
                        + "freshSuccess=true firstAfterInvalidated=true "
                        + "firstAfterReason=owner-window-closed "
                        + "reopenedAfterInvalidated=true "
                        + "reopenedAfterReason=owner-window-closed "
                        + "capabilityContextCaptured=true "
                        + "backgroundSessionAbsent=true client=true change=1");
        acceptance = withText(
                acceptance,
                "reopenedStatus",
                "Capability context reopen probe: "
                        + "retiredBeforeInvalidated=true "
                        + "retiredBeforeReason=owner-window-closed "
                        + "freshSuccess=true retiredAfterInvalidated=true "
                        + "retiredAfterReason=owner-window-closed "
                        + "capabilityContextCaptured=true "
                        + "backgroundSessionAbsent=true client=true change=1");
        acceptance = withNumber(acceptance, "firstPushBaseline", 0);
        acceptance = withNumber(acceptance, "firstPushMessageCount", 1);
        acceptance = withNumber(acceptance, "reopenedPushBaseline", 0);
        acceptance = withNumber(acceptance, "reopenedPushMessageCount", 1);
        acceptance = withNumber(acceptance, "thirdPushBaseline", 0);
        acceptance = withNumber(acceptance, "thirdPushMessageCount", 1);
        acceptance = withNumber(acceptance, "firstRequestCount", 4);
        acceptance = withNumber(acceptance, "firstResponseCount", 4);
        acceptance = withNumber(acceptance, "mainRequestCount", 6);
        acceptance = withNumber(acceptance, "mainResponseCount", 6);
        acceptance = withNumber(acceptance, "reopenedRequestCount", 4);
        acceptance = withNumber(acceptance, "reopenedResponseCount", 4);
        acceptance = withNumber(acceptance, "thirdRequestCount", 4);
        acceptance = withNumber(acceptance, "thirdResponseCount", 4);
        acceptance = withNumber(acceptance, "nativePointerEventCount", 5);
        acceptance = withNumber(
                acceptance, "nativePointerTrustedEventCount", 5);
        acceptance = withText(
                acceptance,
                "nativePointerStages",
                "first-capture,close-a,reopened-probe,close-b,third-probe");
        acceptance = withText(
                acceptance,
                "browserProgrammaticStages",
                "route-navigate,open-a,reopen-b,reopen-c");
        acceptance = withNumber(
                acceptance, "initialProcessIdentifier", 505);
        acceptance = withNumber(
                acceptance, "currentProcessIdentifier", 505);
        acceptance = withNumber(acceptance, "recoveryGeneration", 0);
        return protocolPreservingStringWhitespace(
                "recv",
                "flowCapabilityContextReopen.frameworkAcceptance",
                acceptance);
    }

