    private static String retiredScopeHostEnvelope(
            String direction,
            String type,
            String sessionId,
            String envelopePayload) {
        String wrapper = "recv".equals(direction)
                ? "\"source\":\"java-sidecar\","
                + "\"transport\":\"flow-ipc\","
                + "\"sidecarGeneration\":1,"
                : "\"target\":\"java-sidecar\","
                + "\"transport\":\"flow-ipc\","
                + "\"windowId\":\"capability-reopen-secondary\",";
        return protocolPreservingStringWhitespace(direction, type, """
                {%s"envelope":{"version":1,"type":"%s",
                "id":"retired-scope-%s","correlationId":"%s",
                "sessionId":"%s","uiId":"capability-reopen-secondary",
                "windowId":"capability-reopen-secondary","route":"",
                "payload":%s,"error":null,"timestamp":2}}
                """.formatted(
                wrapper,
                type,
                type,
                RETIRED_SCOPE_HOST_REQUEST_ID,
                sessionId,
                envelopePayload));
    }

