    private static String validCapabilityOwnerWindowCloseTrace() {
        StringBuilder trace = new StringBuilder();
        trace.append(protocol(
                "recv", "launch", "{\"transport\":\"flow-ipc\"}"));
        trace.append(protocol(
                "send", "launch.sidecar",
                "{\"generation\":1,\"transport\":\"flow-ipc\"}"));
        trace.append(protocol(
                "recv", "sidecar.started",
                "{\"generation\":1,\"processIdentifier\":303,"
                        + "\"transport\":\"flow-ipc\"}"));
        trace.append(capabilityGenerationReadyEvent(1));
        trace.append(protocol(
                "recv", "window.create", "{\"windowId\":\"main\"}"));
        trace.append(protocol(
                "recv", "standardBundleReady",
                "{\"requestTransport\":\"opaque-http-stream-ipc\"}"));
        trace.append(protocol(
                "recv", "standardBundleResource",
                "{\"path\":\"/VAADIN/build/FlowClient-owner-close.js\"}"));
        trace.append(protocol(
                "recv", "webview.firstMeaningfulPaint", "{}"));
        trace.append(protocol(
                "send", "opaqueHttpStreamOpen",
                "{\"requestId\":\"owner-close-bootstrap\"}"));
        trace.append(protocol(
                "recv", "opaqueHttpStreamResponse",
                "{\"requestId\":\"owner-close-bootstrap\",\"status\":200}"));
        trace.append(protocol(
                "recv", "opaqueHttpStreamResponseEnd",
                "{\"requestId\":\"owner-close-bootstrap\"}"));
        trace.append(protocol(
                "send", "opaqueHttpStreamOpen",
                "{\"requestId\":\"owner-close-uidl\"}"));
        trace.append(protocol(
                "recv", "opaqueHttpStreamResponse",
                "{\"requestId\":\"owner-close-uidl\",\"status\":200}"));
        trace.append(protocol(
                "recv", "opaqueHttpStreamResponseEnd",
                "{\"requestId\":\"owner-close-uidl\"}"));
        trace.append(protocol(
                "recv", "opaquePushConnected",
                "{\"windowId\":\"main\","
                        + "\"sessionId\":\"flow-ipc-session\","
                        + "\"uiId\":\"main\"}"));
        trace.append(capabilityOwnerClosePointerEvent(
                "secondary-dialog-open", true));
        trace.append(capabilityOwnerCloseCommandEvent());
        trace.append(capabilityOwnerClosePanelObservedEvent());
        trace.append(capabilityOwnerClosePointerEvent(
                "main-owner-close", false));
        trace.append(capabilityOwnerCloseRequestEvent());
        trace.append(capabilityOwnerCloseInvalidationEvent());
        trace.append(capabilityOwnerCloseCompletionDropEvent());
        trace.append(capabilityOwnerCloseResultEvent());
        trace.append(capabilityOwnerCloseWindowClosedEvent());
        trace.append(capabilityOwnerCloseReleasedEvent());
        trace.append(capabilityOwnerClosePointerEvent("main-health", false));
        trace.append(capabilityOwnerCloseAcceptanceEvent());
        trace.append(capabilityOwnerCloseShutdownEvent());
        return trace.toString();
    }

