    private static String capabilityOwnerCloseAcceptanceEvent() {
        String acceptance = allTrue(
                "complete", "standardBundleMode", "rootRendered",
                "flowClientOwned", "opaqueRequestObserved",
                "opaqueResponseObserved", "ownerSecondaryOpenedObserved",
                "secondaryScopeIsolatedObserved", "ownerPanelObserved",
                "ownerPanelAttachedObserved", "ownerPanelVisibleObserved",
                "ownerPanelProductInvalidatedObserved",
                "ownerPanelDetachedObserved", "ownerPanelHiddenObserved",
                "ownerWindowClosedObserved",
                "ownerWindowContextReleasedObserved",
                "windowCloseCommandObserved", "javaListenerObserved",
                "javaTypedInvalidatedOutcomeObserved",
                "capabilityContextCapturedObserved",
                "backgroundSessionAbsentObserved",
                "ownerCloseResultVisibleInMain",
                "mainWindowRetainedObserved", "mainWebViewRetainedObserved",
                "mainProcessRetainedObserved",
                "mainHealthJavaListenerObserved",
                "mainHealthUidlPatchObserved", "nativePointerObserved",
                "nativePointerTrustedObserved",
                "browserProgrammaticSetupObserved", "balancedDrainObserved",
                "resultStableAfterDrain", "errorFree");
        acceptance = withFalse(
                acceptance, "ownerPanelTestCancelInjected", "pushObserved");
        acceptance = withText(
                acceptance, "command", "fileDialog.openFile");
        acceptance = withText(
                acceptance, "typedOutcome", "INVALIDATED");
        acceptance = withText(
                acceptance, "cancelReason", "owner-window-closed");
        acceptance = withText(
                acceptance, "ownerWindowId", "owner-close-secondary");
        acceptance = withText(
                acceptance,
                "ownerSessionId",
                "flow-ipc-window:7B4C4F54-5E8F-4E13-A7B1-3DCE6B165F01");
        acceptance = withText(
                acceptance, "ownerUiId", "owner-close-secondary");
        acceptance = withText(acceptance, "mainWindowId", "main");
        acceptance = withText(
                acceptance, "mainSessionId", "flow-ipc-session");
        acceptance = withText(acceptance, "mainUiId", "main");
        acceptance = withText(
                acceptance,
                "windowStatus",
                "Owner close window: closing=true client=true error=none");
        acceptance = withText(
                acceptance,
                "javaOutcome",
                "Owner close main health: result=outcome=INVALIDATED "
                        + "selected=none "
                        + "cancelReason=owner-window-closed "
                        + "operationInvalidated=true "
                        + "capabilityContextCaptured=true "
                        + "backgroundSessionAbsent=true "
                        + "secondaryClient=true change=1 "
                        + "client=true change=1");
        acceptance = withNumber(acceptance, "requestCount", 6);
        acceptance = withNumber(acceptance, "responseCount", 6);
        acceptance = withNumber(acceptance, "healthRequestBaseline", 5);
        acceptance = withNumber(acceptance, "healthResponseBaseline", 5);
        acceptance = withNumber(
                acceptance, "nativePointerEventCount", 3);
        acceptance = withNumber(
                acceptance, "nativePointerTrustedEventCount", 3);
        acceptance = withText(
                acceptance,
                "nativePointerStages",
                "secondary-dialog-open,main-owner-close,main-health");
        acceptance = withText(
                acceptance,
                "browserProgrammaticStages",
                "route-navigate,secondary-open");
        acceptance = withNumber(
                acceptance, "initialProcessIdentifier", 303);
        acceptance = withNumber(
                acceptance, "currentProcessIdentifier", 303);
        acceptance = withNumber(acceptance, "recoveryGeneration", 0);
        return protocolPreservingStringWhitespace(
                "recv",
                "flowCapabilityOwnerWindowClose.frameworkAcceptance",
                acceptance);
    }

