    private static String validMainWindowCloseRecoveryTrace() {
        StringBuilder trace = new StringBuilder();
        trace.append(protocol(
                "recv", "launch", "{\"transport\":\"flow-ipc\"}"));
        trace.append(protocol(
                "send", "ready",
                "{\"protocolVersion\":1,\"host\":"
                        + "\"swift-appkit-wkwebview\","
                        + "\"transport\":\"flow-ipc\"}"));
        trace.append(protocol(
                "send", "launch.sidecar",
                "{\"generation\":1,\"transport\":\"flow-ipc\"}"));
        trace.append(protocol(
                "recv", "sidecar.started",
                "{\"generation\":1,\"processIdentifier\":101,"
                        + "\"transport\":\"flow-ipc\"}"));
        trace.append(capabilityGenerationReadyEvent(1));
        trace.append(mainCloseRecoveryMainCreateEvent());
        trace.append(protocol(
                "recv", "standardBundleReady",
                "{\"requestTransport\":\"opaque-http-stream-ipc\"}"));
        trace.append(protocol(
                "recv", "standardBundleResource",
                "{\"path\":\"/VAADIN/build/FlowClient-main-close.js\"}"));
        trace.append(protocol(
                "recv", "webview.firstMeaningfulPaint", "{}"));
        for (String requestId : new String[]{
                "main-close-bootstrap", "main-close-uidl"}) {
            trace.append(protocol(
                    "send", "opaqueHttpStreamOpen",
                    "{\"requestId\":\"" + requestId + "\"}"));
            trace.append(protocol(
                    "recv", "opaqueHttpStreamResponse",
                    "{\"requestId\":\"" + requestId
                            + "\",\"status\":200}"));
            trace.append(protocol(
                    "recv", "opaqueHttpStreamResponseEnd",
                    "{\"requestId\":\"" + requestId + "\"}"));
        }
        trace.append(protocol(
                "recv", "opaquePushConnected",
                "{\"windowId\":\"main\","
                        + "\"sessionId\":\"flow-ipc-session\","
                        + "\"uiId\":\"main\"}"));
        trace.append(mainCloseRecoverySecondaryCreateEvent());
        trace.append(mainCloseRecoveryPointerEvent(
                "secondary-close-main", 0));
        trace.append(mainCloseRecoveryCloseCommandEvent());
        trace.append(mainCloseRecoveryCloseResultEvent());
        trace.append(mainCloseRecoveryCloseRequestEvent());
        trace.append(mainCloseRecoveryWindowClosedEvent());
        trace.append(mainCloseRecoveryReleasedEvent());
        trace.append(mainCloseRecoveryFailureInjectionEvent());
        trace.append(mainCloseRecoveryExitEvent());
        trace.append(protocol(
                "send", "launch.sidecar",
                "{\"generation\":2,\"transport\":\"flow-ipc\"}"));
        trace.append(protocol(
                "recv", "sidecar.started",
                "{\"generation\":2,\"processIdentifier\":202,"
                        + "\"transport\":\"flow-ipc\"}"));
        trace.append(capabilityGenerationReadyEvent(2));
        trace.append(mainCloseRecoveryReadyEvent());
        trace.append(mainCloseRecoveryReplayEvent());
        trace.append(mainCloseRecoverySecondWindowClosedSequence());
        trace.append(mainCloseRecoveryPointerEvent("recovered-probe", 1));
        trace.append(mainCloseRecoveryTitleCommandEvent());
        trace.append(mainCloseRecoveryTitleResultEvent());
        trace.append(mainCloseRecoveryAcceptanceEvent());
        trace.append(mainCloseRecoveryShutdownEvent());
        return trace.toString();
    }

