    private static String capabilityDefaultDenyEvents() {
        StringBuilder trace = new StringBuilder();
        trace.append(capabilityDefaultDenyManifestEvent());
        trace.append(capabilityDefaultDenyCommandEvent());
        trace.append(protocolPreservingStringWhitespace(
                "send", "capabilityResult", """
                {"target":"java-sidecar","transport":"flow-ipc",
                "command":"window.setTitle",
                "envelope":{"version":1,"type":"capabilityResult",
                "id":"capability-desktop-command-default-deny",
                "correlationId":"desktop-command-default-deny",
                "sessionId":"flow-ipc-session","uiId":"main",
                "windowId":"main","route":"",
                "payload":{"success":false,"command":"window.setTitle",
                "error":"Command not allowed by desktop-capabilities.json",
                "permissionMode":"manifest-enforced",
                "permissionDecision":"denied",
                "permissionReason":"manifest-denied",
                "permissionScope":"window:main",
                "permissionManifestLoaded":true,
                "permissionManifestPath":"$APP/Contents/Resources/desktop-capabilities.json",
                "permissionManifestCommands":""},
                "error":null,"timestamp":2}}
                """));
        String acceptance = allTrue(
                "complete", "standardBundleMode", "rootRendered",
                "flowClientOwned", "opaqueRequestObserved",
                "opaqueResponseObserved", "javaListenerObserved",
                "uidlPatchObserved", "deniedResultObserved",
                "titleUnchangedObserved", "permissionPayloadPreservedObserved",
                "scopeObserved", "nativePointerObserved",
                "nativePointerTrustedObserved",
                "browserProgrammaticSetupObserved",
                "balancedDrainObserved", "manifestFallbackObserved",
                "errorFree");
        acceptance = withFalse(acceptance, "pushObserved");
        acceptance = withText(acceptance, "windowId", "main");
        acceptance = withText(
                acceptance, "sessionId", "flow-ipc-session");
        acceptance = withText(acceptance, "uiId", "main");
        acceptance = withText(acceptance, "command", "window.setTitle");
        acceptance = withText(
                acceptance, "permissionMode", "manifest-enforced");
        acceptance = withText(
                acceptance, "permissionDecision", "denied");
        acceptance = withText(
                acceptance, "permissionReason", "manifest-denied");
        acceptance = withText(
                acceptance, "permissionScope", "window:main");
        acceptance = acceptance.substring(0, acceptance.length() - 1)
                + ",\"permissionManifestLoaded\":true}";
        acceptance = withText(
                acceptance,
                "permissionManifestPath",
                "$APP/Contents/Resources/desktop-capabilities.json");
        acceptance = withText(
                acceptance, "permissionManifestCommands", "");
        acceptance = withText(
                acceptance,
                "status",
                "Capability permission result: success=false "
                        + "error=Command not allowed by desktop-capabilities.json "
                        + "permissionMode=manifest-enforced "
                        + "permissionDecision=denied permissionReason=manifest-denied "
                        + "permissionScope=window:main command=window.setTitle "
                        + "client=true change=1");
        acceptance = withText(
                acceptance, "initialNativeTitle", "Flow IPC Framework App");
        acceptance = withText(
                acceptance, "finalNativeTitle", "Flow IPC Framework App");
        acceptance = withNumber(
                acceptance, "nativePointerEventCount", 1);
        acceptance = withNumber(
                acceptance, "nativePointerTrustedEventCount", 1);
        acceptance = withText(
                acceptance, "nativePointerStages", "invoke");
        acceptance = withText(
                acceptance, "browserProgrammaticStages", "navigate");
        trace.append(protocolPreservingStringWhitespace(
                "recv",
                "flowCapabilityDefaultDeny.frameworkAcceptance",
                acceptance));
        return trace.toString();
    }

